import type { TroubleCodeGuide } from "./trouble-code-data";

const sx={label:"Honda ServiceExpress",url:"https://techinfo.honda.com/",note:"Honda VIN-specific service information, DTC flowcharts, wiring and service publications"};
const manuals={label:"Honda Owners — CR-V manuals",url:"https://mygarage.honda.com/s/manuals-search",note:"Official model-year warnings, fuel, maintenance and operating information"};
const vtec={label:"Honda Service Bulletin 13-021 — CR-V P2646/P2647",url:"https://static.nhtsa.gov/odi/tsbs/2015/SB-10098946-5233.pdf",note:"All 2002–2009 CR-Vs; intermittent rocker-arm oil-pressure switch branch with switch and O-ring replacement"};
const p1457={label:"Honda Service Bulletin 99-075 — 1998–2001 CR-V P1456/P1457",url:"https://static.nhtsa.gov/odi/tsbs/2013/SB-10053545-3978.pdf",note:"Procedure B separates tank-side P1456 from canister-side P1457 and provides Honda vacuum/FTP tests"};
const evap={label:"Honda Service Bulletin 14-010 — 2012–2013 CR-V P0455/P0456",url:"https://static.nhtsa.gov/odi/tsbs/2014/MC-10129552-9999.pdf",note:"Lists 2012 CR-V except Japan-built vehicles plus specific early 2013 VIN ranges; cap-gasket friction branch"};
const catalyst={label:"Honda 2024 P0420 parts-collection request",url:"https://static.nhtsa.gov/odi/tsbs/2024/MC-11010549-0001.pdf",note:"Expired request for selected 2023–2024 CR-V 1.5L parts; not a repair bulletin, recall or coverage promise"};

const vehicle={name:"Honda CR-V",kicker:"HONDA CR-V · ENGINE, VTEC AND EMISSIONS DIAGNOSTICS",breadcrumb:"Honda CR-V",about:"Honda CR-V engine and emissions diagnostics",yearsIntro:"CR-V diagnostics span the first-generation B20, K24-powered second through fourth generations, 1.5L turbo and 2.4L fifth-generation versions, newer 1.5L turbo models and 2.0L hybrid systems. AWD does not create another engine bank, but engine management, direct injection, turbo plumbing, EVAP packaging, VTEC oil hardware and hybrid operating modes change. Confirm the VIN, market, engine, build plant, emissions label and current Honda campaign status before selecting a flowchart or part."};
type Input=Omit<TroubleCodeGuide,"slug"|"vehicle">&{slug:string};
const article=(x:Input):TroubleCodeGuide=>({...x,slug:`honda/cr-v/${x.slug}`,vehicle});

export const troubleCodeCrv:TroubleCodeGuide[]=[
article({slug:"p0420",code:"P0420",title:"P0420 Code Honda CR-V: Catalyst Diagnosis Before Replacement",description:"Diagnose CR-V P0420 by checking misfire, fuel correction, oil dilution/consumption, exhaust leaks and sensor response before replacing the catalyst.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",severity:"Service soon",driveAdvice:"A steady MIL with normal performance usually permits a short diagnostic trip. Stop for a flashing lamp, severe roughness, raw-fuel odor, converter rattle or major power loss; misfire can overheat the substrate and broken material can block exhaust flow.",quickAnswer:"P0420 means the PCM completed its catalyst monitor and judged Bank 1 oxygen-storage performance below threshold. Every CR-V gasoline four-cylinder has one bank, but it may have more than one catalyst and different A/F/O2 sensor arrangements. Save readiness and freeze data, correct misfire or mixture codes, document oil/coolant use, inspect the exhaust cold and evaluate both sensors under Honda conditions. Honda's November 2024 request involving selected 2023–2024 CR-V 1.5L vehicles was an expired engineering parts-collection message with strict exclusions. It was not a repair bulletin, recall or warranty extension.",symptoms:[{key:"normal",label:"MIL on, driving feels normal",response:"Preserve monitor evidence and test prerequisites before clearing."},{key:"flash",label:"MIL flashes under load",response:"Stop sustained driving and repair the active misfire first."},{key:"rattle",label:"Rattle or weak acceleration",response:"Inspect shields and test for broken/restricted substrate."},{key:"oil",label:"Oil level rises or frequent top-ups",response:"Investigate fuel dilution or oil consumption before a catalyst decision."}],causes:[{cause:"Deteriorated or contaminated catalyst",evidence:"All prerequisites pass and Honda catalyst evaluation fails",firstTest:"VIN/engine-specific catalyst procedure"},{cause:"Misfire or excessive fuel damaged substrate",evidence:"P030x history, flashing MIL, rich correction or fuel-wet plugs",firstTest:"Repair combustion fault first"},{cause:"Oil, fuel-dilution or coolant contamination",evidence:"Fluid change, smoke, deposits or coolant loss",firstTest:"Mechanical/fuel/cooling diagnosis"},{cause:"Exhaust leak around monitored section",evidence:"Cold tick, soot or low-pressure leak evidence",firstTest:"Cold visual and leak test"},{cause:"A/F or O2 sensor/circuit problem",evidence:"Controlled response/electrical test fails",firstTest:"Graph and circuit test"}],freezeFrame:["RPM, load, speed and coolant temperature","Confirmed, pending and permanent codes","Readiness and distance since reset","Fuel correction and cylinder misfire history","Upstream A/F and downstream O2 data","Oil level trend, consumption and exhaust repairs"],steps:[{title:"Preserve monitor history",detail:"Do not clear readiness and permanent-code context before recording it."},{title:"Identify the monitored converter",detail:"Use the exact engine/exhaust diagram; one bank does not mean one catalyst."},{title:"Eliminate catalyst killers",detail:"Repair misfire, rich/lean control, oil burning, dilution and coolant entry first."},{title:"Inspect exhaust cold",detail:"Check flanges, flex section and sensor bungs for soot and leakage."},{title:"Evaluate sensor response",detail:"Use Honda A/F-sensor logic rather than generic narrow-band voltage rules."},{title:"Complete the monitor",detail:"Verify prerequisites and no pending P0420 after an appropriate drive."}],dontReplace:"Do not replace the rear sensor or converter from one code snapshot. A replacement catalyst can fail quickly if misfire, fuel control, oil consumption or coolant entry remains. The expired 2024 parts request does not authorize a repair.",yearNotes:["1997–2001 B20, 2002–2016 K24 and later turbo/hybrid CR-Vs use different exhaust and sensor layouts.","2017+ 1.5L turbo diagnosis adds boost leakage, direct-injection pressure and oil-dilution history.","The 2024 Honda request concerned selected 2023–2024 1.5L vehicles and excluded several companion-code/repair conditions.","Hybrid engine stop/start changes catalyst temperature and monitor opportunities."],faqs:[{question:"Does P0420 prove the catalyst failed?",answer:"No. Upstream engine, exhaust and sensor faults must be excluded."},{question:"Can I drive?",answer:"Usually briefly with a steady lamp; stop for flashing, odor, rattle or power loss."},{question:"Will a rear O2 sensor fix it?",answer:"Only if its circuit or controlled response is proven faulty."},{question:"Does Honda's 2024 message provide coverage?",answer:"No. It was a short-lived engineering parts request."},{question:"Can oil dilution affect diagnosis?",answer:"Yes. Fuel/oil consumption history can reveal conditions that harm catalyst operation."},{question:"Why did a new converter fail?",answer:"The original misfire, mixture, contamination, leak or fitment problem may remain."},{question:"How many banks does a CR-V have?",answer:"Its inline-four has one bank, including AWD models."},{question:"What confirms repair?",answer:"Healthy prerequisites and a completed monitor without pending P0420."}],deepDive:[{heading:"One bank can contain several monitored pieces",paragraphs:["Bank 1 describes the cylinder bank, not the number of converters or sensors. Identify the exact catalyst monitored by the code.","Aftermarket scan graphs without location context can lead to replacing the wrong component."]},{heading:"A catalyst often records earlier damage",paragraphs:["Misfire, rich injection, oil ash and coolant deposits can reduce oxygen storage long after the original symptom disappears.","Review permanent codes, fluid history and prior repairs before judging today's data."]},{heading:"The Honda request must not be misrepresented",paragraphs:["The 2024 message asked dealers to collect parts from narrowly qualified vehicles before repair and then expired.","It documents engineering interest, not a universal defect finding or current consumer remedy."]}],sources:[catalyst,sx,manuals]}),

article({slug:"p0171",code:"P0171",title:"P0171 Code Honda CR-V: Lean Fuel-Trim Diagnosis by Engine",description:"Diagnose CR-V P0171 using idle-versus-load trims, intake and charge-air smoke tests, MAP/MAF plausibility and measured fuel delivery.",definition:"Fuel System Too Lean (Bank 1)",severity:"Diagnose promptly",driveAdvice:"Avoid long trips and hard acceleration when the CR-V hesitates, stalls or shows strongly positive correction. Stop for a flashing MIL, severe power loss, detonation or fuel-pressure warnings. A smooth vehicle with a steady lamp can usually make a short controlled diagnostic trip.",quickAnswer:"P0171 means the PCM added more fuel than its correction limit allowed on the CR-V's only cylinder bank. It does not mean replace the upstream A/F sensor. Compare short- and long-term correction at hot idle, raised rpm and safe load. A large idle-only correction suggests intake, PCV, brake-booster or purge leakage. Correction that worsens with load favors fuel delivery, injector flow or load-sensing error. On 1.5L turbo models, pressure-test charge plumbing and compare low- and high-side fuel data. Older K24 speed-density and later airflow strategies do not support one universal MAF-cleaning fix.",symptoms:[{key:"idle",label:"Rough mostly at idle",response:"Smoke-test manifold, PCV and brake-booster paths and compare at 2,500 rpm."},{key:"load",label:"Hesitates climbing or accelerating",response:"Graph commanded/actual fuel pressure and load; avoid prolonged lean load."},{key:"turbo",label:"Turbo model also lacks boost",response:"Check charge plumbing and P0299 context before sensor replacement."},{key:"service",label:"Code began after air-filter/intake work",response:"Recheck clamps, hoses, seals and sensor connectors."}],causes:[{cause:"Unmetered intake/PCV/booster air",evidence:"Correction highest at idle and improves with rpm",firstTest:"Regulated smoke test"},{cause:"Charge-air leak on 1.5T",evidence:"Lean/load and boost error under pressure",firstTest:"Charge-system pressure/smoke test"},{cause:"Low fuel pressure or injector delivery",evidence:"Correction worsens with demand or pressure misses command",firstTest:"Low/high-side fuel test"},{cause:"MAP/MAF/IAT plausibility fault",evidence:"Load data disagrees with operating condition",firstTest:"Key-on/running signal comparison"},{cause:"Exhaust leak or biased A/F sensor",evidence:"Soot/tick or failed response after mixture causes excluded",firstTest:"Leak then sensor circuit test"}],freezeFrame:["Short/long correction at idle and load","RPM, load, speed and ECT","MAP/MAF/IAT values available on that engine","Commanded/actual fuel pressures","Boost command/actual on turbo engines","Recent intake, injector, purge or engine work"],steps:[{title:"Save learned correction",detail:"A reset deletes the operating-point pattern that guides diagnosis."},{title:"Confirm engine strategy",detail:"B20, K24, 1.5T and hybrid systems expose different useful PIDs."},{title:"Compare three load points",detail:"Hot idle, raised rpm and controlled road load separate leak from delivery patterns."},{title:"Smoke-test the correct path",detail:"Include PCV/booster and turbo charge plumbing where fitted."},{title:"Measure fuel delivery",detail:"Idle pressure alone may miss weak volume or a direct-injection high-side problem."},{title:"Verify correction and pending status",detail:"Repeat the original condition safely after repair."}],dontReplace:"Do not replace an A/F sensor because it reports lean. It may be doing its job. Do not spray flammable cleaner around a running engine or loosen a direct-injection fuel line; use smoke, scan data and specified pressure procedures.",yearNotes:["First-generation B20, K24 generations and 1.5L turbo CR-Vs use different load and fuel systems.","All use one engine bank; AWD does not create Bank 2.","Turbo direct injection requires safe evaluation of low- and high-pressure fuel sides.","Hybrid engine cycling changes how steady-state correction should be captured."],faqs:[{question:"Is P0171 an oxygen-sensor code?",answer:"No. It describes fuel correction reaching a lean limit."},{question:"Can a vacuum leak cause it?",answer:"Yes, especially when correction is highest at idle."},{question:"Should I clean the MAF?",answer:"Only if that engine uses one and data supports contamination."},{question:"Can low fuel pressure cause P0171?",answer:"Yes, commonly under demand."},{question:"Can I drive?",answer:"Limit driving if it hesitates; stop for flashing MIL or major power loss."},{question:"Does AWD change the bank?",answer:"No. The inline-four still has one cylinder bank."},{question:"Why compare trims at several speeds?",answer:"Their pattern separates airflow leakage from fuel-delivery limits."},{question:"What confirms repair?",answer:"Normal correction at idle/load with no pending P0171."}],deepDive:[{heading:"Trim direction matters more than one threshold",paragraphs:["A vacuum leak contributes a larger percentage of total airflow at idle, so its correction often fades as rpm rises.","A weak pump may look acceptable at idle and fall behind when engine demand increases."]},{heading:"Turbo air can escape on either side of the throttle",paragraphs:["Vacuum-side leaks dominate idle; compressed-air leaks often appear under boost.","Test the complete route and do not assume a loose intercooler joint must create a noisy leak."]},{heading:"Generation determines the useful sensor",paragraphs:["Some CR-V calibrations infer airflow primarily from manifold pressure while newer systems provide additional airflow data.","Use agreement among pressure, airflow, throttle and correction instead of a copied grams-per-second rule."]}],sources:[sx,manuals]}),

article({slug:"p0300",code:"P0300",title:"P0300 Code Honda CR-V: Random Misfire Diagnosis",description:"Diagnose CR-V P0300 with cylinder counters, ignition, injectors, fuel correction and compression across K24, 1.5T and hybrid engines.",definition:"Random/Multiple Cylinder Misfire Detected",severity:"Stop soon",driveAdvice:"A flashing MIL means catalyst-damaging active misfire. Ease off and stop as soon as safe. A steady lamp with smooth operation may allow a short diagnostic move, but stop for severe shaking, raw-fuel odor, overheating, low oil pressure or mechanical noise.",quickAnswer:"P0300 records crankshaft-speed disturbances across several cylinders or without a consistent leader. Save P0301–P0304 companions, enhanced counters, freeze data and correction before clearing. One cylinder leading needs a targeted plug/coil/injector/compression path; all four rising together shifts attention to shared fuel pressure, intake/charge leakage, purge flow, timing, voltage or contaminated fuel. A 1.5L turbo adds direct-injection pressure and boost plumbing; a K24 adds valve-clearance and oil-control context. No single Honda bulletin authorizes the same P0300 repair on every CR-V generation.",symptoms:[{key:"flash",label:"MIL flashes and engine shakes",response:"Stop sustained driving to protect the catalyst."},{key:"cold",label:"Misfire only after overnight soak",response:"Capture counters immediately and test cold injector leakage and sealing."},{key:"load",label:"Breaks up climbing or in boost",response:"Test plugs/coils and both fuel-pressure sides under controlled demand."},{key:"all",label:"All four counters rise together",response:"Prioritize shared fuel, air, timing, voltage and purge causes."}],causes:[{cause:"Worn/fouled plugs or weak coil/boot",evidence:"Load-related counts and controlled swap follows",firstTest:"Labelled plug inspection and one coil swap"},{cause:"Injector leakage/restriction or pressure fault",evidence:"Cold/load pattern, pressure mismatch or contribution difference",firstTest:"Fuel-pressure and injector tests"},{cause:"Intake/charge or purge leakage",evidence:"Fuel correction/smoke/bidirectional evidence",firstTest:"Smoke and purge sealing tests"},{cause:"Valve-clearance/compression/timing fault",evidence:"Misfire remains with low relative compression",firstTest:"Compression, leak-down and timing checks"},{cause:"Shared voltage or contaminated fuel",evidence:"Multiple cylinders, voltage/fuel-quality history",firstTest:"Charging waveform and fuel sample"}],freezeFrame:["All-cylinder misfire counters","P0301–P0304 companions","RPM, load, ECT and speed","Fuel correction and fuel pressure","Plug deposits in cylinder order","Recent fueling, valve, injector or turbo work"],steps:[{title:"Preserve the event",detail:"Record counters and freeze data before clearing or swapping parts."},{title:"Find whether one cylinder leads",detail:"Random does not always mean equal; enhanced data can reveal a leader."},{title:"Inspect plugs by cylinder",detail:"Deposits, gap, cracks and wetness direct the next test."},{title:"Use a controlled coil swap",detail:"One evidence-producing swap is useful; repeated swapping is not diagnosis."},{title:"Test shared fuel and air",detail:"Graph pressure, correction and boost while checking purge/intake sealing."},{title:"Prove mechanical health",detail:"Use relative compression then leak-down/valve/timing work as indicated."},{title:"Repeat original conditions",detail:"Verify cold and safe loaded operation without pending misfire."}],dontReplace:"Do not install four coils because the code says multiple. Plugs may be victims of oil, fuel or compression problems. On direct-injection models, never loosen a high-pressure line as a test.",yearNotes:["K24 engines need correct valve-clearance, timing and VTEC oil-system context.","2017+ 1.5T models add charge leaks and low/high fuel-pressure diagnosis.","Hybrid engine stop/start requires appropriate service mode and counter interpretation.","A flashing MIL is urgent regardless of year or drivetrain."],faqs:[{question:"Does P0300 mean all coils failed?",answer:"No. It does not name any component."},{question:"Can I drive?",answer:"Not with a flashing lamp or strong shaking."},{question:"Can injectors cause it?",answer:"Yes, through leakage, restriction or shared pressure problems."},{question:"Should I replace plugs first?",answer:"Inspect and preserve them as evidence before replacement."},{question:"Can tight valves misfire cold?",answer:"Valve sealing/clearance can create temperature-dependent misfire."},{question:"Can bad fuel cause P0300?",answer:"Yes, especially when all cylinders react after refueling."},{question:"Why save cylinder counters?",answer:"They reveal whether one cylinder actually dominates."},{question:"What confirms repair?",answer:"Stable counters under the original condition and no pending P0300."}],deepDive:[{heading:"Random can still have structure",paragraphs:["P0300 matures when no one cylinder fully explains the crank variation, but enhanced counters may show a useful order.","Capture the first cold minute; warm-up can erase injector and sealing patterns."]},{heading:"A plug is evidence before it is maintenance",paragraphs:["Oil ash, fuel wetness, coolant cleaning, cracks and excess gap lead to different diagnoses.","Keep each plug labelled and compare it with its neighbors."]},{heading:"Shared causes deserve shared tests",paragraphs:["Equal counts across cylinders are unlikely to be four simultaneous coil failures.","Fuel pressure, intake leakage, timing, voltage and contaminated fuel can disturb every cylinder together."]}],sources:[sx,manuals]}),

article({slug:"p2646",code:"P2646",title:"P2646 Code Honda CR-V: VTEC Oil-Pressure Switch Diagnosis",description:"Diagnose CR-V P2646 with oil, switch-circuit, screen and pressure tests, including Honda bulletin 13-021's exact 2002–2009 coverage.",definition:"Rocker Arm Oil Pressure Switch Circuit Low Voltage",severity:"Diagnose promptly",driveAdvice:"Keep rpm/load low because the PCM may limit VTEC operation. Stop for the red oil-pressure lamp, low oil, loud valvetrain noise or knock. Those indicate possible lubrication risk beyond the diagnostic code.",quickAnswer:"P2646 means rocker-arm oil-pressure-switch feedback remained low when the PCM expected another state. Low oil, wrong viscosity, a grounded circuit, restricted spool-valve screen/passage, hydraulic pressure loss or the switch can cause it. Honda bulletin 13-021 gives a high-value CR-V branch: every 2002–2009 CR-V is listed for possible intermittent switch failure and switch/O-ring replacement. It does not cover 2010 or newer CR-Vs. Even on a covered vehicle, record oil condition and circuit evidence; if the code returns after the bulletin repair, continue normal hydraulic and electrical troubleshooting.",symptoms:[{key:"limit",label:"Engine will not rev normally",response:"Do not force VTEC engagement; capture command and switch state."},{key:"oil",label:"Oil warning or mechanical noise",response:"Shut down and verify lubrication pressure safely."},{key:"covered",label:"Intermittent on 2002–2009 CR-V",response:"Apply bulletin 13-021's switch/O-ring branch after verification."},{key:"returns",label:"Code returns after switch",response:"Test wiring, screen, passages and actual pressure."}],causes:[{cause:"Low/wrong/degraded engine oil",evidence:"Level, viscosity or service history abnormal",firstTest:"Correct specification and find consumption/leak"},{cause:"Intermittent switch on 2002–2009",evidence:"Exact 13-021 applicability",firstTest:"Bulletin switch/O-ring procedure"},{cause:"Grounded/shorted signal circuit",evidence:"Low state remains with failed loaded circuit test",firstTest:"Connector and circuit test"},{cause:"Restricted spool-valve screen/passage",evidence:"Contamination or slow/low pressure response",firstTest:"Inspect screen and passages"},{cause:"Spool valve or true oil-pressure fault",evidence:"Command present but hydraulic state fails",firstTest:"Honda actuation and pressure test"}],freezeFrame:["Oil level, grade and interval","RPM, load and coolant temperature","VTEC command and switch status","Battery voltage","P2647/P2651/P2652 companions","VIN/year and 13-021 match"],steps:[{title:"Protect lubrication first",detail:"A red oil lamp or noise requires shutdown before VTEC testing."},{title:"Verify 2002–2009 coverage",detail:"Bulletin 13-021 stops at the 2009 CR-V model year."},{title:"Inspect oil and connector",detail:"Look for low/dirty oil, leakage, sludge and terminal contamination."},{title:"Test the switch circuit",detail:"Compare voltage/state to command with the correct K24 schematic."},{title:"Inspect screen and measure pressure",detail:"A switch cannot correct restricted or inadequate oil flow."},{title:"Verify transition",detail:"Confirm correct feedback under safe enable conditions and no pending code."}],dontReplace:"Do not replace the entire spool-valve assembly from P2646 alone. On listed 2002–2009 vehicles Honda identifies the pressure switch and O-ring, but a returning code requires normal diagnosis. Never use thicker oil to conceal pressure loss.",yearNotes:["All 2002–2009 CR-Vs are listed in 13-021.","2010+ CR-Vs are outside that bulletin and require their own flowchart.","P2646/P2651 are low-state variants; P2647/P2652 are high-state variants in the bulletin.","Oil condition is part of the K24 hydraulic control system, not just maintenance history."],faqs:[{question:"Does P2646 mean low engine oil?",answer:"Not necessarily, but level and condition are first safety checks."},{question:"Does 13-021 cover a 2010 CR-V?",answer:"No. CR-V coverage is 2002–2009."},{question:"Can I drive?",answer:"Limit rpm; stop for an oil warning or valvetrain noise."},{question:"Is the spool valve always bad?",answer:"No. Switch, wiring, oil, screen, passages and pressure all matter."},{question:"Why did a new switch not fix it?",answer:"A hydraulic restriction, true pressure issue or circuit fault may remain."},{question:"Can dirty oil cause it?",answer:"Contamination can restrict small VTEC screens and passages."},{question:"Should I rev it to test?",answer:"Only under the approved procedure after oil-pressure safety is established."},{question:"What confirms repair?",answer:"Correct command/feedback transition with no pending P2646."}],deepDive:[{heading:"Low voltage is a state, not a diagnosis",paragraphs:["The PCM observes whether switch feedback agrees with VTEC command.","Both a grounded wire and inadequate hydraulic pressure can hold the signal in the low state."]},{heading:"The CR-V bulletin boundary is unusually clear",paragraphs:["Honda lists every 2002–2009 CR-V and no later CR-V in 13-021.","That makes model year essential; search-keyword similarity cannot extend the remedy."]},{heading:"Oil is hydraulic control fluid here",paragraphs:["The system depends on correct level, viscosity, cleanliness and unobstructed passages.","Correct the cause of low or contaminated oil instead of only topping up."]}],sources:[vtec,sx,manuals]}),

article({slug:"p2647",code:"P2647",title:"P2647 Code Honda CR-V: High-State VTEC Pressure Fault",description:"Diagnose CR-V P2647 by separating an open/high circuit from trapped oil pressure, spool-valve release and the 2002–2009 bulletin switch branch.",definition:"Rocker Arm Oil Pressure Switch Circuit High Voltage",severity:"Diagnose promptly",driveAdvice:"Avoid high rpm and hard acceleration while VTEC feedback is unreliable. Stop for an oil-pressure warning, knock, loud valvetrain noise or very low oil. Do not confuse the DTC with permission to ignore a red lubrication warning.",quickAnswer:"P2647 means the rocker-arm pressure-switch circuit remained high when the PCM expected it to change. An open connector/wire, intermittent switch, spool valve that does not release, restricted return passage or unsuitable oil can create that state. Honda bulletin 13-021 lists every 2002–2009 CR-V for an intermittent switch branch and specifies switch/O-ring replacement. It does not include later CR-V generations. Diagnose command versus feedback and both electrical and hydraulic release; if the fault returns after bulletin work, Honda directs normal troubleshooting.",symptoms:[{key:"limit",label:"Reduced rpm or performance",response:"Capture VTEC command/feedback instead of forcing engagement."},{key:"oil",label:"Oil lamp or noise",response:"Stop and test lubrication first."},{key:"hot",label:"Fault appears only when hot",response:"Graph command, switch state and oil condition during the event."},{key:"covered",label:"2002–2009 intermittent fault",response:"Verify 13-021 and inspect switch connector/O-ring area."}],causes:[{cause:"Open/high-resistance signal circuit",evidence:"High state persists and loaded test fails",firstTest:"Terminal and voltage-drop test"},{cause:"Intermittent switch on listed CR-V",evidence:"2002–2009 model and bulletin conditions",firstTest:"13-021 procedure"},{cause:"Spool valve fails to release",evidence:"Command turns off but hydraulic feedback remains",firstTest:"Actuation and oil-pressure test"},{cause:"Restricted screen/return passage",evidence:"Contamination or delayed state change",firstTest:"Inspect serviceable screen/passages"},{cause:"Incorrect or degraded oil",evidence:"Level/grade/service history abnormal",firstTest:"Correct oil and determine why"}],freezeFrame:["VTEC command and switch state","RPM, load, ECT and battery voltage","Oil level/specification/history","P2646/P2651/P2652 companions","Connector heat/vibration behavior","Model year and bulletin match"],steps:[{title:"Separate oil warning from DTC",detail:"A red lamp/noise demands shutdown regardless of P2647."},{title:"Check bulletin boundary",detail:"Only 2002–2009 CR-Vs use the 13-021 switch branch."},{title:"Graph command versus state",detail:"Identify whether feedback is constant, delayed or heat-sensitive."},{title:"Load-test the circuit",detail:"A continuity beep may miss weak terminal contact."},{title:"Evaluate hydraulic release",detail:"Inspect oil, screen and return passages and measure pressure as specified."},{title:"Verify on and off transitions",detail:"Confirm both states and no pending P2647."}],dontReplace:"Do not treat P2647 as identical to P2646: high versus low state changes the likely electrical and hydraulic faults. Do not extend the 13-021 remedy to 2010+ CR-Vs or repeatedly replace switches after the code returns.",yearNotes:["13-021 covers all 2002–2009 CR-Vs for the intermittent switch branch.","Later CR-V engines and oil-control layouts require separate Honda diagnostics.","P2647/P2652 are high-state variants in the bulletin.","Correct oil level, viscosity and cleanliness affect release as well as pressure buildup."],faqs:[{question:"How is P2647 different from P2646?",answer:"They describe opposite switch-circuit states relative to PCM command."},{question:"Is the switch always bad?",answer:"No. Wiring, valve release, passages and oil can produce the same state."},{question:"Can I drive?",answer:"Limit load; stop for an oil warning or mechanical noise."},{question:"Does 13-021 cover 2011?",answer:"No. Its CR-V range ends at 2009."},{question:"Why load-test wiring?",answer:"Weak terminal contact may pass unloaded continuity."},{question:"Can dirty oil matter?",answer:"Yes, by delaying pressure build or release through small passages."},{question:"What if it returns after switch replacement?",answer:"Continue standard circuit, spool-valve and pressure diagnosis."},{question:"What confirms repair?",answer:"Correct feedback through command-on/off and no pending P2647."}],deepDive:[{heading:"High-state faults have two sides",paragraphs:["An open circuit may read high electrically; trapped oil pressure can keep a healthy switch in the same state.","Command and feedback must be graphed together before choosing a side."]},{heading:"Release flow is part of VTEC operation",paragraphs:["Oil must leave the controlled passage when commanded off.","Sludge or a sticking spool can make pressure feedback linger and mature P2647."]},{heading:"One bulletin does not cover every K24",paragraphs:["Honda chose a specific 2002–2009 CR-V population for 13-021.","A later K24 sharing a code still requires its own service information and test thresholds."]}],sources:[vtec,sx,manuals]}),

article({slug:"p1457",code:"P1457",title:"P1457 Code Honda CR-V: Canister-Side EVAP Leak Tests",description:"Diagnose 1998–2001 CR-V P1457 with Honda Procedure B, canister-side valve tests and safe vacuum/smoke testing rather than a gas-cap guess.",definition:"EVAP Control System Leakage (EVAP Canister System)",severity:"Service soon",driveAdvice:"Short driving is normally acceptable without fuel odor or wetness. Park outdoors and stop if gasoline is visible, vapor odor is strong, tank plumbing is damaged or refueling is abnormal. Keep all ignition sources away and use only EVAP-safe pressure.",quickAnswer:"On the older Honda system, P1457 identifies leakage or failed pressure behavior on the canister side; P1456 identifies the fuel-tank side. Bulletin 99-075 applies Procedure B specifically to 1998–2001 CR-V and updates its HDS, vacuum and component-isolation tests. That means a gas cap is not the default P1457 repair. Inspect the canister plumbing, bypass/vent and purge valves, verify fuel-tank-pressure sensor behavior and section the system. A valve that clicks electrically can still leak or restrict flow mechanically.",symptoms:[{key:"old",label:"1998–2001 CR-V",response:"Use bulletin 99-075 Procedure B, not the Accord/Pilot layout."},{key:"odor",label:"Strong fuel odor",response:"Stop and inspect for liquid leakage safely."},{key:"cap",label:"New cap did not help",response:"Return to canister-side hoses and valve sealing."},{key:"intermittent",label:"Monitor passes sometimes",response:"Test heat/moisture-sensitive valves and preserve found conditions."}],causes:[{cause:"Canister-side hose leak or wrong routing",evidence:"Visual/sectional smoke result",firstTest:"Compare routing and low-pressure smoke"},{cause:"Bypass or vent-shut valve leakage",evidence:"Fails Honda vacuum-hold/command test",firstTest:"Individual valve test"},{cause:"Purge valve does not seal",evidence:"Manifold vacuum reaches EVAP while commanded closed",firstTest:"Closed-state sealing test"},{cause:"Canister/two-way valve fault",evidence:"Other sections pass but pressure behavior fails",firstTest:"Procedure B isolation"},{cause:"FTP sensor/circuit bias",evidence:"Atmospheric/commanded values implausible",firstTest:"Reference, signal and pressure comparison"}],freezeFrame:["Fuel level and ambient/soak temperature","P1456 and circuit companions","FTP sensor voltage/pressure","Purge/vent command and actual sealing","Recent tank/canister/rear-body work","Hose routing and water/corrosion evidence"],steps:[{title:"Confirm model-year system",detail:"The bulletin's CR-V procedure applies to 1998–2001."},{title:"Keep P1456 and P1457 separate",detail:"P1457 directs attention to the canister side, not automatically the cap."},{title:"Inspect hoses and valves",detail:"Check routing, cracks, water intrusion and canister fittings."},{title:"Test sealing, not just clicking",detail:"Apply specified vacuum and commands to prove mechanical closure and flow."},{title:"Section with safe smoke/vacuum",detail:"Use EVAP-regulated equipment and Honda's sequence."},{title:"Complete the monitor",detail:"Verify repair through the service-bay or drive procedure."}],dontReplace:"Do not sell a gas cap as a certain P1457 fix and do not condemn the canister without isolating valves and hoses. Never apply unregulated shop air to a fuel-vapor system.",yearNotes:["99-075 Procedure B lists 1998–2001 CR-V.","P1457 is canister-side; P1456 is fuel-tank-side on this generation.","Later CR-Vs generally use generic P044x codes and different layouts.","Valve sound alone does not establish vacuum sealing or flow."],faqs:[{question:"Is P1457 a loose gas-cap code?",answer:"Not primarily; Honda defines it as canister-side leakage."},{question:"Which CR-V years are in 99-075?",answer:"1998–2001."},{question:"Can I drive?",answer:"Usually briefly without odor or visible fuel."},{question:"What is P1456?",answer:"It points to the tank side on this older strategy."},{question:"Can a clicking valve be faulty?",answer:"Yes. It may leak or be restricted despite clicking."},{question:"Can smoke find the leak?",answer:"Often, when safely regulated and the system is sectioned."},{question:"Should I replace the canister?",answer:"Only after hoses, valves and pressure sensing are tested."},{question:"What confirms repair?",answer:"Correct pressure behavior and a completed EVAP monitor."}],deepDive:[{heading:"The code already narrows the system",paragraphs:["Honda split older EVAP monitoring into tank-side and canister-side regions.","Ignoring that split leads to repeated caps and missed valve or hose faults."]},{heading:"A pressure result can fail without a hole",paragraphs:["The monitor expects valves to route and seal vapor in a timed sequence.","A restricted or leaking valve can imitate a physical opening."]},{heading:"Procedure B is CR-V-specific",paragraphs:["Bulletin 99-075 groups the early CR-V with Civic for this layout.","The Accord/Pilot Procedure A uses different steps and should not be substituted."]}],sources:[p1457,sx,manuals]}),

article({slug:"p0135",code:"P0135",title:"P0135 Code Honda CR-V: Upstream Sensor Heater Circuit Test",description:"Diagnose CR-V P0135 by checking the Bank 1 Sensor 1 heater feed, control, current, resistance and heat-damaged harness before sensor replacement.",definition:"Oxygen Sensor Heater Circuit Malfunction (Bank 1, Sensor 1)",severity:"Service soon",driveAdvice:"A heater-only fault normally allows brief driving, but cold-start emissions and fuel control may worsen. Stop for flashing misfire, repeatedly blown fuses, melted wiring or exhaust damage. Allow the manifold and catalyst to cool before touching connectors.",quickAnswer:"P0135 means the PCM did not observe expected electrical behavior from the heater in Bank 1 Sensor 1, the upstream feedback sensor. Honda may name it a primary heated oxygen or air/fuel ratio sensor depending on year. Verify the exact connector and diagram, then test loaded battery feed, shared fuse/relay, terminal grip, heater resistance/current and PCM-controlled side. A resistance value or universal sensor copied from another CR-V generation can be wrong. Multiple heater codes strongly favor a shared feed or harness problem.",symptoms:[{key:"cold",label:"MIL returns just after cold start",response:"Capture heater command/current before exhaust heat changes resistance."},{key:"fuse",label:"Fuse opens again",response:"Locate the short; never install a larger fuse."},{key:"multiple",label:"More than one heater code",response:"Check shared supply and grounds before sensors."},{key:"repair",label:"Started after exhaust work",response:"Inspect routing, swapped connectors and pin damage."}],causes:[{cause:"Open upstream heater element",evidence:"VIN-correct cold resistance/current test fails",firstTest:"Element resistance and current"},{cause:"Missing fused power",evidence:"Voltage absent or collapses under load",firstTest:"Fuse/relay/feed voltage drop"},{cause:"PCM-control wire fault",evidence:"Command exists but control path fails",firstTest:"Loaded control-circuit test"},{cause:"Heat/chafe/corrosion at harness",evidence:"Visual or wiggle/temperature dropout",firstTest:"Connector/loom inspection"},{cause:"Incorrect replacement sensor",evidence:"Fault began after repair; part/calibration mismatch",firstTest:"VIN part verification"}],freezeFrame:["Battery voltage, ECT and time since start","Heater command/current if supported","All heater/voltage codes","Fuse state","Recent exhaust/engine work","Engine, emissions label and sensor part"],steps:[{title:"Identify upstream sensor",detail:"Bank 1 Sensor 1 is before the monitored catalyst; connector route varies."},{title:"Read every code",detail:"Shared heater or low-voltage codes change the first test."},{title:"Inspect cold",detail:"Check for melted/chafed loom and terminal damage near hot exhaust."},{title:"Test supply under load",detail:"Open-circuit voltage can hide resistance that collapses during heater current."},{title:"Test element and PCM control",detail:"Use the exact model-year pinout and specification."},{title:"Verify from cold soak",detail:"Confirm normal heater behavior and no pending P0135."}],dontReplace:"Do not buy a sensor before testing its feed and control, and do not substitute the downstream sensor. Never upsize a fuse. A manifold-mounted sensor and harness remain hot after shutdown.",yearNotes:["B20, K24, 1.5T and hybrid sensors differ in type, location and heater specification.","The inline-four has one bank, but Sensor 1 versus Sensor 2 remains critical.","Aftermarket universal wiring can introduce resistance or reversed connections.","Use VIN/emissions calibration rather than thread size to select a sensor."],faqs:[{question:"Which sensor is B1S1?",answer:"The upstream feedback sensor before the monitored catalyst."},{question:"Does P0135 prove the sensor signal is bad?",answer:"No. It identifies the heater circuit."},{question:"Can I drive?",answer:"Usually briefly if operation is normal and wiring/fuses are safe."},{question:"Can a fuse cause it?",answer:"Yes, but determine why it opened."},{question:"Can I test resistance?",answer:"Yes, with the exact Honda spec and correct heater terminals."},{question:"Why several heater codes?",answer:"They may share a fuse, relay or supply branch."},{question:"Will a universal sensor work?",answer:"It risks incorrect heater/signal characteristics."},{question:"What confirms repair?",answer:"Normal cold-start heater current and no pending P0135."}],deepDive:[{heading:"Honda sensor names evolved",paragraphs:["Generic scanners may say oxygen sensor while Honda service information calls the upstream unit an A/F sensor.","Identify function and wiring, not only the generic label."]},{heading:"Loaded voltage exposes weak connections",paragraphs:["A corroded terminal can show battery voltage with no current and fail when the heater turns on.","Voltage-drop and current tests reveal circuit capacity."]},{heading:"A blown fuse is a clue",paragraphs:["Repeated opening points toward a shorted heater, chafed loom or another load on the branch.","A larger fuse can turn the fault into harness damage or fire."]}],sources:[sx,manuals]}),

article({slug:"p0455",code:"P0455",title:"P0455 Code Honda CR-V: Large EVAP Leak and 14-010 Check",description:"Diagnose CR-V P0455 using cap evidence, purge/vent sealing, tank-pressure data and safe smoke testing, with exact 2012–2013 bulletin limits.",definition:"EVAP System Large Leak Detected",severity:"Service soon",driveAdvice:"A steady P0455 with no fuel smell usually allows short driving. Park outdoors and stop for strong odor, visible gasoline, tank damage or refueling spit-back. Keep ignition sources away and never use uncontrolled compressed air.",quickAnswer:"P0455 means the EVAP monitor could not create or retain expected pressure; it does not locate the opening. Record cap position, fuel level, FTP data and recent tank work, then prove purge/vent valve sealing and use EVAP-safe smoke. Honda bulletin 14-010 covers 2012 CR-V except Japan-built vehicles and narrow early-production 2013 2WD/AWD VIN ranges. It identifies excess cap-gasket friction that can keep the cap from sealing and calls for inspection/replacement when matched. It is not a universal cap answer for every CR-V.",symptoms:[{key:"fill",label:"Lamp followed refueling",response:"Record cap's found condition before tightening."},{key:"year",label:"2012 or early 2013 CR-V",response:"Check build origin/VIN against 14-010."},{key:"start",label:"Hard start after filling",response:"Test purge valve closed-state leakage."},{key:"odor",label:"Strong fuel odor",response:"Stop and inspect for liquid leakage safely."}],causes:[{cause:"Cap not sealed/damaged/wrong",evidence:"Found condition or cap/filler test fails",firstTest:"Cap and neck inspection"},{cause:"14-010 cap-gasket friction branch",evidence:"Exact 2012–2013 VIN/build match",firstTest:"Bulletin inspection"},{cause:"Purge valve stuck open",evidence:"Vacuum passes when commanded closed",firstTest:"Closed-state sealing test"},{cause:"Vent valve/hose/canister leak",evidence:"Cannot seal; smoke localizes escape",firstTest:"Command and smoke test"},{cause:"Tank/pump seal or FTP bias",evidence:"Recent service or pressure signal implausible",firstTest:"Sectional leak and signal test"}],freezeFrame:["Fuel level, ambient and soak temperature","FTP sensor data","Purge/vent commands","P0456/P0441/circuit companions","Cap condition and recent refuel","VIN/build plant and tank service"],steps:[{title:"Preserve cap evidence",detail:"Tightening first removes the most perishable clue."},{title:"Check bulletin applicability",detail:"Build origin and published 2013 VIN cutoffs matter."},{title:"Prove valve sealing",detail:"A solenoid click does not prove it closes."},{title:"Apply regulated smoke",detail:"Inspect filler, hoses, canister and top-of-tank seals."},{title:"Validate FTP response",detail:"A biased sensor can report a leak in a sealed system."},{title:"Complete EVAP monitor",detail:"Meet fuel/soak conditions and check pending status."}],dontReplace:"Do not replace a cap and canister together. Bulletin 14-010 is limited to specified 2012–2013 production and its cap-friction condition. A disconnected pump seal or leaking purge valve needs a different repair.",yearNotes:["2012 CR-V coverage excludes Japan-produced vehicles in 14-010.","2013 coverage is limited to published early 2WD/AWD VIN ranges.","1998–2001 P1456/P1457 logic should not be mixed with later P0455 systems.","Later generations may use revised capless/filler and canister layouts."],faqs:[{question:"Is P0455 always a gas cap?",answer:"No. Valves, hoses, canister, tank seals and sensing can cause it."},{question:"Does 14-010 cover every 2013 CR-V?",answer:"No. It lists early-production VIN ranges."},{question:"Can I drive?",answer:"Usually briefly without odor or liquid fuel."},{question:"Can purge leakage cause hard starting?",answer:"Yes, especially after refueling."},{question:"Can I use shop air?",answer:"Not unregulated; use EVAP-safe low pressure."},{question:"Why did a new cap not fix it?",answer:"The leak/valve may be elsewhere or the filler surface damaged."},{question:"Why is readiness incomplete?",answer:"Fuel level, soak and temperature gate the monitor."},{question:"What confirms repair?",answer:"Correct sealing/FTP response and completed monitor."}],deepDive:[{heading:"Build origin changes the bulletin branch",paragraphs:["Honda explicitly excluded Japan-built 2012 CR-Vs and listed separate 2013 VIN ranges.","Year and model alone are insufficient for applying 14-010."]},{heading:"A valve can imitate a large hole",paragraphs:["Purge and vent passages are supposed to close during portions of the test.","A valve held open lets pressure escape without a cracked tank."]},{heading:"The cap's condition is evidence",paragraphs:["Note whether it was loose, cross-threaded or felt sticky before changing it.","Also inspect the filler sealing surface; a correct cap cannot seal damage beneath it."]}],sources:[evap,sx,manuals]}),

article({slug:"p0128",code:"P0128",title:"P0128 Code Honda CR-V: Thermostat and Warm-Up Curve Diagnosis",description:"Diagnose CR-V P0128 with cold-soak sensor comparison, recorded warm-up, fan checks and generation-correct thermostat verification.",definition:"Coolant Thermostat (Coolant Temperature Below Thermostat Regulating Temperature)",severity:"Service soon",driveAdvice:"Slow warm-up usually is not an emergency, but stop for overheating, steam, coolant loss, a temperature warning or heater output suddenly turning cold. If coolant is full when checked cold and temperature stays stable, a short data-recording trip is generally reasonable.",quickAnswer:"P0128 means coolant temperature remained below the PCM's modeled regulating range after enough calculated warm-up. A thermostat stuck open is common, but first compare ECT and intake-air temperature after an overnight soak; both should be close to ambient before start. Graph ECT with time, speed, load, fan command and cabin heat. Low coolant, air pockets, a cold-biased sensor, fans running unnecessarily or an incorrect thermostat can duplicate the code. Turbo and hybrid CR-Vs warm differently, so elapsed minutes and a dashboard gauge are not sufficient diagnosis.",symptoms:[{key:"heat",label:"Cabin warms slowly",response:"Check coolant cold and record the full warm-up."},{key:"road",label:"ECT falls at highway speed",response:"Confirm thermostat leakage with the graph."},{key:"gauge",label:"Gauge looks normal",response:"Use scan data; the display is damped."},{key:"hot",label:"Temperature rises or coolant leaks",response:"Stop and diagnose overheating rather than P0128."}],causes:[{cause:"Thermostat stuck open/incorrect",evidence:"Slow rise and highway temperature drop",firstTest:"Cold-start ECT graph"},{cause:"ECT sensor/circuit biased cold",evidence:"Cold ECT differs from IAT/ambient",firstTest:"Cold-soak comparison"},{cause:"Low coolant/trapped air",evidence:"Low level, recent service or unstable heat",firstTest:"Pressure/leak check and bleed"},{cause:"Unwanted fan operation",evidence:"Fans run cold with A/C off/no command",firstTest:"Command versus actual test"},{cause:"Invalid load/temperature input",evidence:"Companion DTC or implausible freeze data",firstTest:"Resolve input fault"}],freezeFrame:["ECT/IAT/measured ambient","Time, rpm, load and speed","Fan command and A/C request","Coolant level/recent work","Heater output/outside temperature","Companion voltage/load/temperature codes"],steps:[{title:"Begin after cold soak",detail:"A thermostat cannot create a pre-start ECT/IAT mismatch."},{title:"Inspect cooling system cold",detail:"Never open a hot pressurized system."},{title:"Graph the whole warm-up",detail:"Capture rise, regulation and highway drop."},{title:"Observe fan command and action",detail:"Separate normal A/C request from an electrical fault."},{title:"Verify correct thermostat and bleeding",detail:"Engine generation controls part and air-removal procedure."},{title:"Retest comparably",detail:"Confirm stable regulation and no pending P0128."}],dontReplace:"Do not replace a thermostat before checking cold sensor plausibility. A wrong-temperature part or trapped air can make P0128 return, while low coolant can create a much more dangerous overheating problem.",yearNotes:["B20, K24 and 1.5T engines use different thermostat locations/specifications.","Hybrid engine-off periods reduce heat input by design.","Cold ambient and strong heater demand affect warm-up but do not invalidate a repeated monitor failure.","Use scan ECT, not only the blue lamp or gauge."],faqs:[{question:"Is P0128 always a thermostat?",answer:"No. ECT bias, low coolant, air and fan faults can mimic it."},{question:"Can I drive?",answer:"Usually briefly if coolant is full and temperature stable."},{question:"Why does the gauge look normal?",answer:"It is damped over a broad temperature range."},{question:"Can winter weather set it?",answer:"It changes warm-up, but the PCM uses enable logic."},{question:"Can fuel economy drop?",answer:"Yes, prolonged warm-up affects enrichment."},{question:"Can I open the radiator hot?",answer:"No; pressurized coolant can cause burns."},{question:"Why compare ECT and IAT?",answer:"Both should approach ambient during a long soak."},{question:"What confirms repair?",answer:"Plausible cold values and stable regulation without pending P0128."}],deepDive:[{heading:"Cold comparison isolates sensing",paragraphs:["Before start, coolant and intake hardware have had time to approach the same ambient temperature.","A large mismatch points to sensing/circuit error before thermostat testing begins."]},{heading:"Highway airflow is revealing",paragraphs:["A thermostat that leaks open may let temperature fall as radiator airflow rises.","Graph vehicle speed and engine load with ECT to preserve that relationship."]},{heading:"Hybrid clock time is not engine run time",paragraphs:["The gasoline engine can stop while the CR-V remains ready.","Use hybrid service mode and its monitor procedure rather than comparing with a conventional K24."]}],sources:[sx,manuals]}),

article({slug:"p0301",code:"P0301",title:"P0301 Code Honda CR-V: Cylinder 1 Misfire Diagnosis",description:"Diagnose CR-V P0301 with correct cylinder identification, plug evidence, one controlled coil swap, injector testing and compression.",definition:"Cylinder 1 Misfire Detected",severity:"Stop soon",driveAdvice:"Stop driving when the MIL flashes or the engine shakes strongly because raw fuel can overheat the catalyst. With a steady lamp and mild intermittent fault, restrict movement to diagnosis and avoid boost, high rpm and heavy loads.",quickAnswer:"P0301 means the PCM counted excessive misfire on cylinder 1; it does not name a coil. Confirm cylinder numbering from the exact B20, K24, L15 turbo or hybrid engine diagram. Save cold/load counters, keep plugs in order and make one controlled coil swap. If the count stays on cylinder 1, test injector command/delivery and compression/leak-down. Cold-start injector leakage, tight valve clearance, a cracked plug or direct-injection pressure problem can all look like a coil fault. Honda has no one P0301 bulletin that supplies the same repair for every CR-V generation.",symptoms:[{key:"flash",label:"MIL flashes",response:"Stop sustained driving to protect the catalyst."},{key:"cold",label:"Only cylinder 1 misfires cold",response:"Capture immediately and test cold injector leakage and sealing."},{key:"swap",label:"Counter follows coil swap",response:"Inspect boot/connector and replace the proven component."},{key:"stays",label:"Counter remains on cylinder 1",response:"Move to injector and compression tests."}],causes:[{cause:"Cylinder 1 plug fouled/worn/cracked",evidence:"Abnormal deposit, gap or insulation",firstTest:"Labelled plug comparison"},{cause:"Coil/boot/connector fault",evidence:"Misfire follows controlled swap or circuit fails",firstTest:"One swap and loaded circuit test"},{cause:"Injector leak/restriction/circuit",evidence:"Count stays; contribution/delivery differs",firstTest:"Injector balance/leak/command tests"},{cause:"Valve-clearance or compression fault",evidence:"Low relative/measured compression",firstTest:"Compression and leak-down"},{cause:"Air leak near cylinder 1 runner",evidence:"Idle trim/misfire and localized smoke evidence",firstTest:"Intake smoke test"}],freezeFrame:["Cylinder 1/all-cylinder counts","RPM, load, ECT and speed","Fuel correction/pressure","Plug 1 versus neighboring plugs","Compression/leak-down","Recent injector, valve or engine work"],steps:[{title:"Confirm cylinder 1",detail:"Do not rely on a generic left/right image."},{title:"Preserve cold/load behavior",detail:"Test before warm-up hides the pattern."},{title:"Inspect plug and boot",detail:"Photograph wetness, deposits, cracks and gap."},{title:"Perform one coil swap",detail:"Watch whether the enhanced count actually moves."},{title:"Test injector and sealing",detail:"If it stays, prove fuel delivery and compression."},{title:"Verify cold and loaded",detail:"Repeat the original condition without provoking a flashing MIL."}],dontReplace:"Do not replace four coils for P0301. A fresh plug may temporarily hide oil, injector or mechanical trouble. Direct-injection fuel circuits require Honda pressure-relief and safety procedures.",yearNotes:["Cylinder layout is inline-four, but access/routing differs among B20, K24, 1.5T and hybrid engines.","K24 valve-clearance and timing condition can create cylinder-specific misfire.","1.5T direct injection adds high-side pressure and injector leakage tests.","A flashing MIL requires the same urgent response on AWD and FWD."],faqs:[{question:"Is P0301 always a coil?",answer:"No. Plug, injector, wiring, compression, valve and intake faults can cause it."},{question:"Can I drive?",answer:"Not with flashing MIL or severe shaking."},{question:"Can I swap coils?",answer:"Yes, carefully, while observing whether the counter follows."},{question:"What if it stays on cylinder 1?",answer:"Test injector delivery/circuit and compression."},{question:"Can valve clearance cause it?",answer:"Yes, through poor sealing, often temperature-dependent."},{question:"Should I clear first?",answer:"No. Preserve counters and freeze data."},{question:"Can a runner leak affect one cylinder?",answer:"Yes, especially at idle."},{question:"What confirms repair?",answer:"No rising cylinder 1 count under the original condition."}],deepDive:[{heading:"One swap answers one question",paragraphs:["Move coil 1 to a known cylinder and reproduce the condition safely.","If the count does not move, stop swapping and test fuel/mechanical causes."]},{heading:"The original plug should be retained",paragraphs:["Fuel wetness, oil ash, coolant cleaning and cracks tell different stories.","Mixing plugs or discarding them destroys cylinder evidence."]},{heading:"Cold diagnosis has a short window",paragraphs:["Injector leakage and valve sealing may normalize as temperature changes.","Record the first start rather than diagnosing only after a road test."]}],sources:[sx,manuals]}),
];
